"""API refusals only: no dataset/groups are generated by these prerequisites."""
import unittest
from group_data import group_dataset,partition_groups
class GroupAPITests(unittest.TestCase):
    def test_no_original_validation_or_TEST_endpoint(self):
        for role in ('test','validation','unknown'):
            with self.assertRaises(ValueError):group_dataset(0,role)
    def test_fixed_fold_noise_and_variant_domain(self):
        for fold in (-1,2,True,'0'):
            with self.assertRaises(ValueError):partition_groups(fold)
        for args in ((0,'fit',1,6),(0,'heldout',2,6),(0,'fit',0,6.),(0,'fit',0,1)):
            with self.assertRaises(ValueError):group_dataset(*args)
